INSERT INTO states (name, slug, short_description, description, start_year, end_year, capital, founder, government, religion, region, hero_image, status) VALUES
('Asya Hun Devleti', 'asya-hun-devleti', 'Orta Asya bozkırlarında büyük siyasi birlik kuran erken Türk devleti.', 'Asya Hun Devleti, bozkır teşkilatlanması, askeri düzen ve diplomasi açısından sonraki Türk devletlerini etkileyen güçlü bir siyasi yapıdır.', -220, 216, 'Ötüken çevresi', 'Teoman', 'Kağanlık', 'Gök Tanrı inancı', 'Orta Asya', 'https://images.unsplash.com/photo-1519681393784-d120267933ba?auto=format&fit=crop&w=1200&q=80', 'published'),
('Avrupa Hun Devleti', 'avrupa-hun-devleti', 'Attila döneminde Avrupa siyasetinin merkezine yerleşen Hun devleti.', 'Avrupa Hun Devleti, Kavimler Göçü çağında askeri gücü ve diplomatik baskısıyla Roma dünyasının dengelerini değiştirmiştir.', 375, 469, 'Etzelburg', 'Balamir', 'Kağanlık', 'Gök Tanrı inancı', 'Doğu Avrupa', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80', 'published'),
('Akhunlar', 'akhunlar', 'Orta Asya, İran ve Hindistan hattında etkili olan Hun mirası taşıyan devlet.', 'Akhunlar, ticaret yolları ve askeri hareketlilik üzerinden geniş bir coğrafyada siyasi etki kurmuştur.', 420, 567, 'Belh çevresi', 'Bilinmiyor', 'Kağanlık', 'Çeşitli inançlar', 'Orta Asya', 'https://images.unsplash.com/photo-1533105079780-92b9be482077?auto=format&fit=crop&w=1200&q=80', 'published'),
('Göktürk Kağanlığı', 'gokturk-kaganligi', 'Türk adını devlet adı olarak kullanan ilk büyük kağanlık.', 'Göktürk Kağanlığı, bozkır siyasetini yazılı kültür, diplomasi ve güçlü askeri yapı ile birleştirerek Türk tarihinin merkezi halkalarından biri olmuştur.', 552, 744, 'Ötüken', 'Bumin Kağan', 'Kağanlık', 'Gök Tanrı inancı', 'Orta Asya', 'https://images.unsplash.com/photo-1518998053901-5348d3961a04?auto=format&fit=crop&w=1200&q=80', 'published'),
('İkinci Göktürk Kağanlığı', 'ikinci-gokturk-kaganligi', 'Kutluk Kağan ile yeniden bağımsızlık kazanan Göktürk devamı.', 'İkinci Göktürk Kağanlığı, Orhun Yazıtları ile hem siyasi hem kültürel hafızada ayrıcalıklı bir yere sahiptir.', 682, 744, 'Ötüken', 'Kutluk Kağan', 'Kağanlık', 'Gök Tanrı inancı', 'Orta Asya', 'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=1200&q=80', 'published'),
('Uygur Kağanlığı', 'uygur-kaganligi', 'Yerleşik kültür, yazı ve ticaretle öne çıkan kağanlık.', 'Uygur Kağanlığı, bozkır geleneğini şehirleşme, ticaret ve yazılı kültürle zenginleştirmiştir.', 744, 840, 'Ordu-Balık', 'Kutluk Bilge Kül Kağan', 'Kağanlık', 'Maniheizm ve Budizm', 'Orta Asya', 'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=1200&q=80', 'published'),
('Avar Kağanlığı', 'avar-kaganligi', 'Orta Avrupa’da etkili olan Türk kökenli kağanlık.', 'Avar Kağanlığı, askeri teknolojisi ve siyasi baskısıyla Bizans ve Avrupa tarihinde iz bırakmıştır.', 562, 823, 'Panonya', 'Bayan Kağan', 'Kağanlık', 'Çeşitli inançlar', 'Orta Avrupa', 'https://images.unsplash.com/photo-1473773508845-188df298d2d1?auto=format&fit=crop&w=1200&q=80', 'published'),
('Hazar Kağanlığı', 'hazar-kaganligi', 'Kafkasya ve Karadeniz kuzeyinde ticaret yollarını kontrol eden devlet.', 'Hazar Kağanlığı, çok dinli ve çok kültürlü yapısıyla Avrasya ticaretinde stratejik bir konuma sahipti.', 650, 969, 'İtil', 'Bilinmiyor', 'Kağanlık', 'Çeşitli inançlar', 'Kafkasya', 'https://images.unsplash.com/photo-1493246507139-91e8fad9978e?auto=format&fit=crop&w=1200&q=80', 'published'),
('Karahanlılar', 'karahanlilar', 'İslamiyet’i kabul eden ilk büyük Türk hanedanlarından biri.', 'Karahanlılar, Türk-İslam kültürünün oluşumunda şehir, medrese ve edebiyat ekseninde belirleyici rol oynamıştır.', 840, 1212, 'Balasagun', 'Bilge Kül Kadir Han', 'Hanlık', 'İslam', 'Maveraünnehir', 'https://images.unsplash.com/photo-1548013146-72479768bada?auto=format&fit=crop&w=1200&q=80', 'published'),
('Gazneliler', 'gazneliler', 'Horasan, Afganistan ve Kuzey Hindistan hattında yükselen Türk devleti.', 'Gazneliler, askeri seferleri ve kültürel himayeleriyle Türk-İslam tarihinin önemli devletlerindendir.', 963, 1186, 'Gazne', 'Alp Tigin', 'Sultanlık', 'İslam', 'Horasan', 'https://images.unsplash.com/photo-1604147706283-d7119b5b822c?auto=format&fit=crop&w=1200&q=80', 'published'),
('Büyük Selçuklu Devleti', 'buyuk-selcuklu-devleti', 'Türk-İslam dünyasının siyasi merkezini yeniden şekillendiren büyük devlet.', 'Büyük Selçuklu Devleti, Anadolu’nun kapılarını açan siyasi ve askeri hamleleriyle İslam dünyasında koruyucu güç haline gelmiştir.', 1037, 1194, 'Rey, İsfahan', 'Tuğrul Bey', 'Sultanlık', 'İslam', 'İran ve Horasan', 'https://images.unsplash.com/photo-1544947950-fa07a98d237f?auto=format&fit=crop&w=1200&q=80', 'published'),
('Harzemşahlar', 'harzemsahlar', 'Ceyhun çevresinde yükselen ve Moğol istilasıyla karşılaşan Türk-İslam devleti.', 'Harzemşahlar, Selçuklu sonrası dönemde bölgesel gücü temsil etmiş, Moğol yayılmasıyla tarih sahnesinde kritik rol oynamıştır.', 1097, 1231, 'Gürgenç', 'Anuş Tigin', 'Sultanlık', 'İslam', 'Harzem', 'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=1200&q=80', 'published'),
('Anadolu Selçuklu Devleti', 'anadolu-selcuklu-devleti', 'Anadolu’da Türk-İslam şehirleşmesinin temelini atan devlet.', 'Anadolu Selçuklu Devleti, kervansarayları, medreseleri ve siyasi örgütlenmesiyle Anadolu’nun dönüşümünde belirleyici olmuştur.', 1077, 1308, 'İznik, Konya', 'Süleyman Şah', 'Sultanlık', 'İslam', 'Anadolu', 'https://images.unsplash.com/photo-1524231757912-21f4fe3a7200?auto=format&fit=crop&w=1200&q=80', 'published'),
('Altın Orda', 'altin-orda', 'Deşt-i Kıpçak sahasında kurulan güçlü bozkır devleti.', 'Altın Orda, Doğu Avrupa ve Karadeniz kuzeyindeki siyasi ve ticari ağlarda uzun süre etkili olmuştur.', 1242, 1502, 'Saray', 'Batu Han', 'Hanlık', 'İslam', 'Deşt-i Kıpçak', 'https://images.unsplash.com/photo-1519681393784-d120267933ba?auto=format&fit=crop&w=1200&q=80', 'published'),
('Osmanlı Devleti', 'osmanli-devleti', 'Beylikten imparatorluğa dönüşen uzun ömürlü Türk devleti.', 'Osmanlı Devleti, üç kıtaya yayılan siyasi düzeni, kurumları ve kültürel mirasıyla dünya tarihinin büyük imparatorluklarından biridir.', 1299, 1922, 'Bursa, Edirne, İstanbul', 'Osman Gazi', 'Monarşi', 'İslam', 'Anadolu ve Balkanlar', 'https://images.unsplash.com/photo-1524231757912-21f4fe3a7200?auto=format&fit=crop&w=1200&q=80', 'published');
INSERT INTO rulers (state_id, name, slug, birth_year, death_year, reign_start, reign_end, biography, achievements, image) VALUES
((SELECT id FROM states WHERE slug='asya-hun-devleti'), 'Mete Han', 'mete-han', -234, -174, -209, -174, 'Mete Han, Asya Hun siyasi birliğini güçlendiren ve bozkır askeri teşkilatını sistemleştiren hükümdar olarak bilinir.', 'Onlu askeri teşkilat geleneği ve merkezi otoritenin güçlendirilmesiyle öne çıkar.', ''),
((SELECT id FROM states WHERE slug='avrupa-hun-devleti'), 'Attila', 'attila', 395, 453, 434, 453, 'Attila, Avrupa Hun Devleti’nin en güçlü dönemine liderlik etmiş ve Roma siyaseti üzerinde büyük baskı kurmuştur.', 'Diplomasi, seferler ve merkezi otoriteyle Hun gücünü Avrupa’nın merkezine taşımıştır.', ''),
((SELECT id FROM states WHERE slug='gokturk-kaganligi'), 'Bumin Kağan', 'bumin-kagan', NULL, 552, 552, 552, 'Bumin Kağan, Göktürk Kağanlığı’nın kurucusu olarak Türk adını devlet adı haline getiren siyasi hareketin lideridir.', 'Avar hâkimiyetinden çıkış ve bağımsız kağanlığın kuruluşu en önemli başarısıdır.', ''),
((SELECT id FROM states WHERE slug='ikinci-gokturk-kaganligi'), 'Bilge Kağan', 'bilge-kagan', 683, 734, 716, 734, 'Bilge Kağan, İkinci Göktürk Kağanlığı’nın güçlü hükümdarı ve Orhun Yazıtları’nın merkez kişiliklerinden biridir.', 'Devlet düzenini sağlamlaştırmış, Tonyukuk ve Kül Tigin ile birlikte siyasi istikrarı korumuştur.', ''),
((SELECT id FROM states WHERE slug='buyuk-selcuklu-devleti'), 'Alp Arslan', 'alp-arslan', 1029, 1072, 1063, 1072, 'Alp Arslan, Büyük Selçuklu Devleti’nin Anadolu kapılarını açan hükümdarıdır.', 'Malazgirt Zaferi ile Anadolu tarihinin yönünü değiştirmiştir.', ''),
((SELECT id FROM states WHERE slug='buyuk-selcuklu-devleti'), 'Melikşah', 'meliksah', 1055, 1092, 1072, 1092, 'Melikşah döneminde Büyük Selçuklu Devleti siyasi, kültürel ve idari açıdan zirveye ulaşmıştır.', 'Nizamiye medreseleri ve idari düzenin güçlenmesi bu dönemin önemli gelişmeleridir.', ''),
((SELECT id FROM states WHERE slug='osmanli-devleti'), 'Osman Gazi', 'osman-gazi', 1258, 1326, 1299, 1326, 'Osman Gazi, Osmanlı Beyliği’nin kurucusu kabul edilen liderdir.', 'Beyliğin siyasi temelini atmış ve uç bölgesinde kalıcı bir güç oluşturmuştur.', ''),
((SELECT id FROM states WHERE slug='osmanli-devleti'), 'Fatih Sultan Mehmet', 'fatih-sultan-mehmet', 1432, 1481, 1451, 1481, 'Fatih Sultan Mehmet, İstanbul’un fethiyle Osmanlı Devleti’ni imparatorluk düzeyine taşıyan hükümdardır.', 'İstanbul’un fethi, merkezi devlet düzeninin güçlenmesi ve kanunnamelerle öne çıkar.', '');
INSERT INTO wars (name, slug, date_text, year, location, result, description, background, battle, aftermath, importance, map_image) VALUES
('Malazgirt Savaşı', 'malazgirt-savasi', '26 Ağustos 1071', 1071, 'Malazgirt', 'Selçuklu zaferi', 'Büyük Selçuklu Devleti ile Bizans arasında yapılan ve Anadolu tarihini değiştiren savaş.', 'Bizans’ın doğu seferi ve Selçuklu ilerleyişi iki gücü Malazgirt’te karşı karşıya getirdi.', 'Alp Arslan komutasındaki Selçuklu ordusu hareketli süvari taktikleriyle Bizans ordusunu yıprattı.', 'Zaferden sonra Anadolu’da Türk yerleşimi hızlandı.', 'Anadolu’nun Türkleşme sürecinde sembolik ve stratejik bir dönüm noktasıdır.', ''),
('İstanbul’un Fethi', 'istanbulun-fethi', '29 Mayıs 1453', 1453, 'İstanbul', 'Osmanlı zaferi', 'Osmanlı Devleti’nin Bizans başkentini fethederek yeni bir çağı başlattığı kuşatma.', 'İstanbul, Osmanlı toprak bütünlüğü ve ticaret yolları açısından stratejik konumdaydı.', 'Kuşatma toplar, donanma hamlesi ve yoğun kara harekâtıyla yürütüldü.', 'Şehir Osmanlı başkenti oldu ve imparatorluk merkezi güçlendi.', 'Dünya tarihinde Orta Çağ’dan Yeni Çağ’a geçiş sembollerinden biri kabul edilir.', ''),
('Pasinler Savaşı', 'pasinler-savasi', '1048', 1048, 'Pasinler', 'Selçuklu zaferi', 'Selçuklular ile Bizans-Gürcü kuvvetleri arasındaki erken dönem Anadolu mücadelesi.', 'Selçuklu akınları Bizans sınırında yeni bir askeri gerilim oluşturdu.', 'Selçuklu kuvvetleri bölgedeki birleşik Bizans-Gürcü gücünü mağlup etti.', 'Anadolu seferleri için siyasi özgüven arttı.', 'Malazgirt öncesi Selçuklu-Bizans mücadelesinin önemli halkasıdır.', '');
INSERT INTO state_wars (state_id, war_id) VALUES
((SELECT id FROM states WHERE slug='buyuk-selcuklu-devleti'), (SELECT id FROM wars WHERE slug='malazgirt-savasi')),
((SELECT id FROM states WHERE slug='buyuk-selcuklu-devleti'), (SELECT id FROM wars WHERE slug='pasinler-savasi')),
((SELECT id FROM states WHERE slug='osmanli-devleti'), (SELECT id FROM wars WHERE slug='istanbulun-fethi'));
INSERT INTO ruler_wars (ruler_id, war_id) VALUES
((SELECT id FROM rulers WHERE slug='alp-arslan'), (SELECT id FROM wars WHERE slug='malazgirt-savasi')),
((SELECT id FROM rulers WHERE slug='fatih-sultan-mehmet'), (SELECT id FROM wars WHERE slug='istanbulun-fethi'));
INSERT INTO cultures (title, slug, category, summary, content, image) VALUES
('Orhun Yazıtları', 'orhun-yazitlari', 'Yazılı kültür', 'Türk adının, devlet aklının ve siyasi öğüdün taş üzerine yazıldığı kaynaklar.', 'Orhun Yazıtları, Türk tarihinin en önemli yazılı belgeleri arasında yer alır. Devlet yönetimi, halkla ilişki ve bağımsızlık fikri açısından güçlü mesajlar taşır.', ''),
('Toy Geleneği', 'toy-gelenegi', 'Sosyal hayat', 'Siyasi ve toplumsal kararların görüşüldüğü kurultay geleneği.', 'Toy, hükümdarın çevresindeki beylerle birlikte karar aldığı ve toplumsal düzeni temsil eden önemli bir kurumdur.', '');
INSERT INTO epics (name, slug, related_people, summary, content, image) VALUES
('Oğuz Kağan Destanı', 'oguz-kagan-destani', 'Oğuz Kağan', 'Türk destan geleneğinde soy, fetih ve düzen fikrini işleyen temel anlatılardan biri.', 'Oğuz Kağan Destanı, hükümdarlık, cihan hakimiyeti ve boy düzeni gibi temaları mitolojik bir dille aktarır.', ''),
('Ergenekon Destanı', 'ergenekon-destani', 'Göktürkler', 'Yeniden doğuş ve bağımsızlık temasını taşıyan güçlü anlatı.', 'Ergenekon anlatısı, sıkışmışlıktan çıkış, demiri eritme ve yeni bir başlangıç simgeleriyle hafızada yer eder.', '');
