('Osmanlı Tarihi', 'Halil İnalcık', 'Türkiye İş Bankası Kültür Yayınları', 2009, '', 'Kitap');
INSERT INTO timeline_events (title, slug, year_start, year_end, description, event_type, related_content_id) VALUES
('Asya Hun siyasi birliğinin güçlenmesi', 'asya-hun-siyasi-birligi', -209, -174, 'Mete Han döneminde merkezi otorite ve askeri düzen güç kazandı.', 'devlet', (SELECT id FROM states WHERE slug='asya-hun-devleti')),
('Göktürk Kağanlığı’nın kuruluşu', 'gokturk-kaganligi-kurulus', 552, NULL, 'Bumin Kağan önderliğinde bağımsız Göktürk Kağanlığı kuruldu.', 'devlet', (SELECT id FROM states WHERE slug='gokturk-kaganligi')),
('Orhun Yazıtları dönemi', 'orhun-yazitlari-donemi', 732, 735, 'Kül Tigin ve Bilge Kağan yazıtları Türk yazılı hafızasının temel metinleri oldu.', 'kultur', (SELECT id FROM cultures WHERE slug='orhun-yazitlari')),
('Malazgirt Zaferi', 'malazgirt-zaferi', 1071, NULL, 'Alp Arslan komutasındaki Selçuklu ordusu Bizans ordusunu mağlup etti.', 'savas', (SELECT id FROM wars WHERE slug='malazgirt-savasi')),
('İstanbul’un Fethi', 'istanbulun-fethi-timeline', 1453, NULL, 'Fatih Sultan Mehmet İstanbul’u fethederek Osmanlı Devleti’ni imparatorluk merkezi haline getirdi.', 'savas', (SELECT id FROM wars WHERE slug='istanbulun-fethi'));
